//! The Activity focus: the Jobs list and the Job detail, read from the
//! node's promises. A running import shows in the list with its bar and
//! in the detail with its counts and current file; a job that does not
//! say how far it is shows no bar; a click on a row changes the detail;
//! Cancel works from both panels and Retry from the detail; the status
//! bar's indicator opens the focus on the job clicked; with real
//! viewports the focus has an OS window of its own, brought forward when
//! asked again. The snapshots (`tests/snapshots/activity-*.png`) are
//! regenerated by the box's `gui-snapshots` job with `test=activity_focus`.
//!
//! The node is the desktop's (`VaultService` in process) with stand-in
//! runners, held until the test lets them end.

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use egui::{ViewportId, vec2};
use egui_kittest::Harness;
use egui_kittest::kittest::Queryable as _;
use egui_pop::api::windows::WindowId;
use egui_pop::core::indicator;
use helios_core::jobs::Jobs;
use helios_gui::shell::ACTIVITY_WINDOW;
use helios_gui::{Shell, headless, helios_panels};
use helios_inspect::client::Client;
use helios_node_core::endpoint::VaultService;
use helios_node_core::promises::{Handle, Promises};
use helios_shell::commands::Origin;
use helios_vault::promises::{Promise, State};
use helios_vault::{MemoryStore, Vault};
use serde_json::{Value, json};

/// What the stand-in runners are told.
#[derive(Default)]
struct Gate {
    /// Every held runner ends with this report.
    end: AtomicBool,
    /// The ids of the promises their runner saw cancelled.
    cancelled: Mutex<Vec<String>>,
}

/// Runs a stand-in job as its request's `script` says: `bar` (120 of
/// 412, `IMG_0120.JPG`), `spin` (3 so far, no total), `fail` (fails, then
/// succeeds on its retry), held until cancelled or the gate ends them.
fn run(gate: &Gate, handle: &Handle<MemoryStore>) {
    let script = handle.request()["script"]
        .as_str()
        .unwrap_or("bar")
        .to_string();
    match script.as_str() {
        "fail" if handle.promise().attempts < 2 => {
            return handle.failed("the disk is full", true);
        }
        "fail" => {
            return handle.done(json!({
                "report": { "added": 410, "skipped": 0, "failed": 2 },
                "failed": [
                    { "path": "/card/DCIM/IMG_0007.JPG", "error": "unreadable" },
                    { "path": "/card/DCIM/IMG_0009.JPG", "error": "unreadable" },
                ],
            }));
        }
        "spin" => handle.progress(3, None, Some("scanning")),
        _ => handle.progress(120, Some(412), Some("IMG_0120.JPG")),
    }
    let deadline = Instant::now() + Duration::from_secs(30);
    loop {
        if handle.cancel_asked() {
            gate.cancelled.lock().unwrap().push(handle.id().to_string());
            return handle.cancelled();
        }
        if gate.end.load(Ordering::SeqCst) {
            return handle.done(json!({ "report": { "added": 412 } }));
        }
        if Instant::now() > deadline {
            return handle.failed("timed out", false);
        }
        std::thread::sleep(Duration::from_millis(10));
    }
}

/// The desktop's node on a library in memory, its promises' runners the
/// stand-ins `gate` controls.
fn node(gate: &Arc<Gate>) -> (Arc<Client>, Arc<Promises<MemoryStore>>) {
    let bus = Arc::new(helios_core::Bus::new());
    let vault = Arc::new(Vault::new(MemoryStore::default()));
    let jobs = Jobs::new(bus.clone());
    let mut promises = Promises::new(vault.clone(), jobs.clone());
    for kind in ["import", "trash"] {
        let gate = gate.clone();
        promises = promises.kind(kind, true, move |handle| run(&gate, &handle));
    }
    let promises = Arc::new(promises);
    let service = VaultService::new(vault, bus, jobs, "test").with_promises(promises.clone());
    let client = Arc::new(Client::in_process(Arc::new(service)).with_origin("user"));
    (client, promises)
}

fn start(promises: &Promises<MemoryStore>, kind: &str, label: &str, script: &str) -> Promise {
    promises
        .start(
            kind,
            label,
            json!({ "script": script, "origin": "agent", "source": "EOS_DIGITAL" }),
        )
        .unwrap()
}

fn shell_on(client: Arc<Client>) -> Harness<'static, Shell> {
    let mut shell = Shell::new(helios_panels(), None);
    shell.follow_activity(client);
    let mut h = headless::harness(shell, vec2(1280.0, 800.0));
    h.run_steps(3);
    h
}

/// Steps frames until `done` holds, for ten seconds at most.
fn until(h: &mut Harness<'_, Shell>, what: &str, done: impl Fn(&Harness<'_, Shell>) -> bool) {
    let deadline = Instant::now() + Duration::from_secs(10);
    while Instant::now() < deadline {
        h.step();
        if done(h) {
            return;
        }
        std::thread::sleep(Duration::from_millis(20));
    }
    panic!("never got there: {what}");
}

fn focus(h: &Harness<'_, Shell>) -> Value {
    h.state().activity_focus_state()
}

fn open(h: &mut Harness<'_, Shell>, id: &str) {
    h.state_mut()
        .run("activity.show", json!({ "id": id }), Origin::User)
        .unwrap();
    h.run_steps(3);
}

fn row_bar(h: &Harness<'_, Shell>, id: &str) -> Option<bool> {
    focus(h)["rows"]
        .as_array()?
        .iter()
        .find(|r| r["id"] == id)
        .and_then(|r| r["bar"].as_bool())
}

/// The leftmost node labelled `label`: the Jobs list's.
fn in_list<'a>(h: &'a Harness<'_, Shell>, label: &'a str) -> egui_kittest::Node<'a> {
    h.get_all_by_label(label)
        .min_by(|a, b| a.rect().min.x.total_cmp(&b.rect().min.x))
        .unwrap_or_else(|| panic!("no {label}"))
}

/// The rightmost node labelled `label`: the Job detail's.
fn in_detail<'a>(h: &'a Harness<'_, Shell>, label: &'a str) -> egui_kittest::Node<'a> {
    h.get_all_by_label(label)
        .max_by(|a, b| a.rect().min.x.total_cmp(&b.rect().min.x))
        .unwrap_or_else(|| panic!("no {label}"))
}

#[test]
fn a_running_import_shows_with_its_bar_and_counts_and_a_job_without_progress_has_none() {
    let gate = Arc::new(Gate::default());
    let (client, promises) = node(&gate);
    let import = start(&promises, "import", "Import 412 photos", "bar");
    let trash = start(&promises, "trash", "Empty the trash", "spin");
    let mut h = shell_on(client);
    open(&mut h, &import.id);
    until(&mut h, "both jobs listed", |h| {
        row_bar(h, &import.id).is_some() && row_bar(h, &trash.id).is_some()
    });
    until(&mut h, "the import's bar", |h| {
        row_bar(h, &import.id) == Some(true)
    });
    assert_eq!(focus(&h)["selected"], json!(import.id));
    // No bar for a job that does not say how far it is.
    assert_eq!(row_bar(&h, &trash.id), Some(false));
    // The detail: the counts (the row says them too) and the file at hand.
    until(&mut h, "the import's counts", |h| {
        h.get_all_by_label("120 of 412").count() == 2
    });
    assert!(h.query_by_label("IMG_0120.JPG").is_some());
    assert!(h.query_by_label("An agent").is_some());
    // A click on the trash's row selects it: the detail follows.
    in_list(&h, "Empty the trash").click();
    h.run_steps(3);
    assert_eq!(focus(&h)["selected"], json!(trash.id));
    until(&mut h, "the trash's detail", |h| {
        h.query_by_label("3 so far").is_some() && h.query_by_label("scanning").is_some()
    });
    // Cancel from the detail stops it.
    in_detail(&h, "Cancel").click();
    until(&mut h, "the trash cancelled", |_| {
        gate.cancelled.lock().unwrap().contains(&trash.id)
    });
    // Cancel from the list, on the import's row hovered.
    until(&mut h, "the trash settled", |h| {
        h.get_all_by_label("Cancel").count() == 0
    });
    let row = in_list(&h, "Import 412 photos").rect().center();
    h.hover_at(row);
    h.run_steps(3);
    in_list(&h, "Cancel").click();
    until(&mut h, "the import cancelled", |_| {
        gate.cancelled.lock().unwrap().contains(&import.id)
    });
}

#[test]
fn retry_from_the_detail_runs_a_failed_job_again() {
    let gate = Arc::new(Gate::default());
    let (client, promises) = node(&gate);
    let failing = start(&promises, "import", "Import 412 photos", "fail");
    let mut h = shell_on(client);
    open(&mut h, &failing.id);
    until(&mut h, "the failure", |h| {
        h.query_by_label("Retry").is_some()
    });
    assert!(
        h.get_all_by_label("Failed: the disk is full").count() >= 1,
        "the reason shows"
    );
    h.get_by_label("Retry").click();
    // Run again, it ends with its outcome: the counts, the failed files.
    until(&mut h, "the outcome", |h| {
        h.query_by_label("Show in Library").is_some()
    });
    assert!(h.query_by_label("410").is_some());
    assert!(h.query_by_label("IMG_0007.JPG").is_some());
    assert_eq!(h.get_all_by_label("unreadable").count(), 2);
    assert!(h.query_by_label("Retry").is_none());
}

fn shown(h: &Harness<'_, Shell>, id: &str) -> Option<indicator::Record> {
    indicator::find(&h.ctx, id).filter(|r| r.shown)
}

/// Clicks indicator `id` of the status bar.
fn click(h: &mut Harness<'_, Shell>, id: &str) {
    let [x, y, w, hh] = shown(h, id).unwrap_or_else(|| panic!("no {id}")).rect;
    let centre = egui::pos2(x + w / 2.0, y + hh / 2.0);
    h.hover_at(centre);
    h.step();
    h.drag_at(centre);
    h.step();
    h.drop_at(centre);
    h.step();
}

#[test]
fn the_status_bar_opens_the_focus_on_the_job_clicked() {
    let gate = Arc::new(Gate::default());
    let (client, promises) = node(&gate);
    let main = start(&promises, "import", "Import 412 photos", "bar");
    let _other = start(&promises, "trash", "Empty the trash", "spin");
    let mut h = shell_on(client);
    until(&mut h, "the indicator", |h| {
        shown(h, helios_gui::activity::MARK).is_some()
    });
    assert_eq!(focus(&h)["open"], false);
    click(&mut h, helios_gui::activity::MARK);
    until(&mut h, "the focus open", |h| focus(h)["open"] == true);
    // The main job (the oldest running) is the one the bar showed.
    assert_eq!(focus(&h)["selected"], json!(main.id));
    // A failure's badge selects the failure.
    let failed = start(&promises, "import", "Import 3 photos", "fail");
    until(&mut h, "the badge", |h| {
        shown(h, helios_gui::activity::FAILED_MARK).is_some()
    });
    click(&mut h, helios_gui::activity::FAILED_MARK);
    until(&mut h, "the failure selected", |h| {
        focus(h)["selected"] == json!(failed.id)
    });
    until(&mut h, "the badge seen", |h| {
        shown(h, helios_gui::activity::FAILED_MARK).is_none()
    });
    gate.end.store(true, Ordering::SeqCst);
}

/// The windows the main window's last pass declared, as eframe would
/// open them.
fn declared(h: &Harness<'static, Shell>) -> Vec<ViewportId> {
    h.output()
        .viewport_output
        .iter()
        .filter(|(v, o)| **v != ViewportId::ROOT && o.viewport_ui_cb.is_some())
        .map(|(v, _)| *v)
        .collect()
}

#[test]
fn the_activity_focus_opens_in_its_own_window() {
    let mut h = headless::harness(Shell::new(helios_panels(), None), vec2(1280.0, 800.0));
    h.ctx.set_embed_viewports(false);
    h.state_mut().draw_frame(true);
    h.run();
    assert!(declared(&h).is_empty(), "no window but the main one");
    h.state_mut()
        .run("activity.show", Value::Null, Origin::User)
        .unwrap();
    h.run_steps(3);
    let windows = declared(&h);
    assert_eq!(windows.len(), 1, "the focus's own window: {windows:?}");
    let app = h.state().app().handle().clone();
    assert_eq!(
        app.window_viewport(&WindowId::new(ACTIVITY_WINDOW)),
        Some(windows[0])
    );
    // Asked again: the same window, not a second one.
    h.state_mut()
        .run("activity.show", Value::Null, Origin::User)
        .unwrap();
    h.run_steps(3);
    assert_eq!(declared(&h), windows);
    // Closed: the focus closes, the main window stays.
    app.close_window(&WindowId::new(ACTIVITY_WINDOW));
    h.run_steps(3);
    assert!(declared(&h).is_empty());
    assert_eq!(focus(&h)["open"], false);
}

/// Promises of known times, for the pictures: a running import, a scan
/// without a total, a failed import and a finished one.
fn pictured() -> Vec<Promise> {
    let at = 1_794_650_000;
    let promise = |id: &str, kind: &str, label: &str, state: State, created: u64| Promise {
        id: id.into(),
        owner: format!("{kind}-{id}"),
        kind: kind.into(),
        label: label.into(),
        request: json!({ "origin": "user", "source": "EOS_DIGITAL" }),
        state,
        cancel_asked: false,
        attempts: 1,
        created,
        updated: at,
    };
    vec![
        promise(
            "promise-4",
            "trash",
            "Empty the trash",
            State::Running {
                done: 3,
                total: None,
                note: Some("scanning".into()),
            },
            at - 12,
        ),
        promise(
            "promise-3",
            "import",
            "Import 412 photos",
            State::Running {
                done: 120,
                total: Some(412),
                note: Some("IMG_0120.JPG".into()),
            },
            at - 95,
        ),
        promise(
            "promise-2",
            "import",
            "Import 3 photos",
            State::Failed {
                reason: "the disk is full".into(),
                retryable: true,
            },
            at - 600,
        ),
        promise(
            "promise-1",
            "export",
            "Export 12 photos",
            State::Done {
                result: json!({ "report": { "added": 12 } }),
            },
            at - 900,
        ),
    ]
}

#[test]
fn activity_snapshots() {
    let mut results = egui_kittest::SnapshotResults::new();
    let mut h = headless::harness(Shell::new(helios_panels(), None), vec2(1280.0, 800.0));
    h.state_mut().show_activity_at(pictured(), 1_794_650_000);
    for (id, name) in [
        ("promise-3", "activity-running-pop-dark-1x"),
        ("promise-2", "activity-failed-pop-dark-1x"),
    ] {
        open(&mut h, id);
        // The spinners repaint for ever: a few frames, not a settled run.
        h.run_steps(4);
        results.add(h.try_snapshot(name));
    }
}
